{
  "name": "magpie-gemini-search",
  "version": "0.1.1",
  "description": "Google Search Grounding hook plugin for Magpie (AI Studio API, multi-key failover, redirect resolution)",
  "type": "module",
  "main": "./index.mjs",
  "files": [
    "index.mjs",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "magpie",
    "magpie-plugin",
    "opencode",
    "opencode-plugin",
    "gemini",
    "google-search",
    "grounding",
    "search"
  ],
  "author": "qq136692547-cmyk",
  "homepage": "https://github.com/qq136692547-cmyk/magpie-gemini-search#readme",
  "bugs": {
    "url": "https://github.com/qq136692547-cmyk/magpie-gemini-search/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/qq136692547-cmyk/magpie-gemini-search.git"
  },
  "license": "MIT",
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "test": "node --test index.test.mjs"
  },
  "magpie": {
    "name": "Google Search Grounding",
    "icon": "data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><circle cx='11' cy='11' r='7' fill='none' stroke='%234285F4' stroke-width='2'/><line x1='16' y1='16' x2='21' y2='21' stroke='%23EA4335' stroke-width='2' stroke-linecap='round'/></svg>",
    "maxConcurrency": 4,
    "options": {
      "model": "gemini-3.8-flash",
      "includeSummary": true,
      "resolveRedirects": false
    },
    "summary": {
      "en": "Google Search Grounding via AI Studio API with multi-key failover and optional redirect resolution.",
      "zh": "通过 AI Studio API 实现谷歌搜索落地引文：支持多 Key 容灾和可选重定向解析。"
    }
  }
}
